# Surah Al-Anfal (chapter 8) — part 2: ayat 9-18 (IDs 1169-1178)
SURAH = 8

ENTRIES = {
1169: (
"یاد کرو — جب — تم — اپنے رب — سے — مدد — مانگتے تھے — تو اس نے — تمہاری پکار کا جواب دیا — بے شک — میں — تمہاری — ہزار فرشتوں سے — مدد کروں گا — ایک کے بعد ایک",
"""۱۔ بدر میں — اللہ کی غیبی مدد۔
۲۔ ’’إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَۃِ مُرْدِفِينَ‘‘ — یاد کرو — جب — تم — اپنے رب — سے — مدد — مانگتے تھے — تو اس نے — تمہاری پکار کا جواب دیا — بے شک — میں — تمہاری — ہزار فرشتوں سے — مدد کروں گا — ایک کے بعد ایک — یعنی اللہ — مؤمنوں کی پکار سن کر — فرشتوں سے — مدد فرماتا ہے۔
۳۔ عملی سبق: مشکل میں — اللہ سے — پکار مانگو۔"""
),
1170: (
"اور — اللہ — نے — اسے — صرف — ایک — خوش خبری — بنایا — اور — اس لیے — کہ — تمہارے دل — مطمئن ہوں — اور — مدد — صرف اللہ کی طرف سے ہے — بے شک — اللہ — زبردست حکمت والا ہے",
"""۱۔ فرشتوں کی مدد — دلوں کی تسلی کے لیے۔
۲۔ ’’وَمَا جَعَلَهُ اللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِ قُلُوبُكُمْ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّهِ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ‘‘ — اور — اللہ — نے — اسے — صرف — ایک — خوش خبری — بنایا — اور — اس لیے — کہ — تمہارے دل — مطمئن ہوں — اور — مدد — صرف اللہ کی طرف سے ہے — بے شک — اللہ — زبردست حکمت والا ہے — یعنی اصل مدد — اللہ کی ہے — فرشتے — صرف تسلی کے لیے۔
۳۔ عملی سبق: مدد — اللہ سے مانگو؛ ظاہر وسائل — صرف مدد کا ذریعہ ہیں۔"""
),
1171: (
"یاد کرو — جب — وہ — تمہیں — نیند — سے ڈھانپ دیتا ہے — اس کی طرف سے — امن — اور — تم پر آسمان سے — پانی — اتارتا ہے — تاکہ — تمہیں — اس سے — پاک کرے — اور — تم سے — شیطان کی نجاست — دور کرے — اور — تمہارے دلوں پر — باندھ دے — اور — اس کے ذریعے — تمہارے پاؤں — مضبوط کرے",
"""۱۔ بدر میں — اللہ کی نعمتیں — نیند، بارش اور سکون۔
۲۔ ’’إِذْ يُغَشِّيكُمُ النُّعَاسَ أَمَنَۃً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ السَّمَاءِ مَاءً لِّيُطَهِّرَكُم بِهِ وَيُذْهِبَ عَنكُمْ رِجْزَ الشَّيْطَانِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ الْأَقْدَامَ‘‘ — یاد کرو — جب — وہ — تمہیں — نیند — سے ڈھانپ دیتا ہے — اس کی طرف سے — امن — اور — تم پر آسمان سے — پانی — اتارتا ہے — تاکہ — تمہیں — اس سے — پاک کرے — اور — تم سے — شیطان کی نجاست — دور کرے — اور — تمہارے دلوں پر — باندھ دے — اور — اس کے ذریعے — تمہارے پاؤں — مضبوط کرے — یعنی بدر میں — اللہ کی طرف سے — نیند، بارش اور سکون — سب — فتح کی تیاری کے لیے تھے۔
۳۔ عملی سبق: اللہ کی مدد — ظاہری اور باطنی — دونوں — پہلوؤں میں — ملتی ہے۔"""
),
1172: (
"یاد کرو — جب — تمہارا رب — فرشتوں کو وحی کرتا ہے — کہ — میں — تمہارے ساتھ ہوں — پس — ان — لوگوں کو — جو ایمان لائے — ثابت قدمی عطا کرو — عنقریب — میں — کافروں کے دلوں میں — خوف ڈالوں گا — پس — گردن پر ضرب لگاؤ — اور ان کی ہر پور — پر ضرب لگاؤ",
"""۱۔ اللہ کی وحی — فرشتوں کو — مؤمنوں کی حمایت کا حکم۔
۲۔ ’’إِذْ يُوحِي رَبُّكَ إِلَى الْمَلَائِكَۃِ أَنِّي مَعَكُمْ فَثَبِّتُوا الَّذِينَ آمَنُوا سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْأَعْنَاقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍ‘‘ — یاد کرو — جب — تمہارا رب — فرشتوں کو وحی کرتا ہے — کہ — میں — تمہارے ساتھ ہوں — پس — ان — لوگوں کو — جو ایمان لائے — ثابت قدمی عطا کرو — عنقریب — میں — کافروں کے دلوں میں — خوف ڈالوں گا — پس — گردن پر ضرب لگاؤ — اور ان کی ہر پور — پر ضرب لگاؤ — یعنی فرشتوں کو — مؤمنوں کی مدد اور کافروں کی ہلاکت — کا حکم دیا گیا۔
۳۔ عملی سبق: اللہ کی حمایت — مؤمنوں کو — ثابت قدم — رکھتی ہے۔"""
),
1173: (
"یہ — اس لیے کہ — انہوں نے — اللہ اور اس کے رسولؐ — کا مقابلہ کیا — اور — جو — اللہ اور اس کے رسولؐ — سے مقابلہ کرے — بے شک — اللہ — سخت عذاب دینے والا ہے",
"""۱۔ کافروں کی سزا — اللہ اور رسولؐ سے مقابلہ کرنے کا نتیجہ۔
۲۔ ’’ذَٰلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ وَرَسُولَهُ فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ‘‘ — یہ — اس لیے کہ — انہوں نے — اللہ اور اس کے رسولؐ — کا مقابلہ کیا — اور — جو — اللہ اور اس کے رسولؐ — سے مقابلہ کرے — بے شک — اللہ — سخت عذاب دینے والا ہے — یعنی اللہ اور رسولؐ سے مقابلہ — سب سے بڑا جرم — ہے۔
۳۔ عملی سبق: اللہ اور رسولؐ کے ساتھ — دشمنی سے بچو۔"""
),
1174: (
"یہ — چکھو — اور — بے شک — کافروں کے لیے — آگ کا عذاب ہے",
"""۱۔ کافروں کی سزا — دنیا کی ذلت اور آخرت کی آگ۔
۲۔ ’’ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَافِرِينَ عَذَابَ النَّارِ‘‘ — یہ — چکھو — اور — بے شک — کافروں کے لیے — آگ کا عذاب ہے — یعنی دنیا میں — شکست — اور آخرت — میں آگ کا عذاب — کافروں کا مقدر ہے۔
۳۔ عملی سبق: کفر — دونوں جہانوں میں — خسران ہے۔"""
),
1175: (
"اے ایمان والو — جب — تم — کافروں سے — جنگ — کے لیے — ملو — تو — ان — سے منہ نہ موڑو",
"""۱۔ مؤمنوں کو — جنگ میں — ثابت قدمی کا حکم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا زَحْفًا فَلَا تُوَلُّوهُمُ الْأَدْبَارَ‘‘ — اے ایمان والو — جب — تم — کافروں سے — جنگ — کے لیے — ملو — تو — ان — سے منہ نہ موڑو — یعنی جنگ میں — مؤمنوں کو — پیٹھ پھیرنے سے منع کیا گیا ہے۔
۳۔ عملی سبق: جنگ میں — جم کر کھڑے رہو؛ پیٹھ نہ موڑو۔"""
),
1176: (
"اور — جو کوئی — اُس دن — ان سے — منہ موڑے — سوائے اس کے کہ — جنگی چال — کے طور پر ہو — یا — کسی گروہ کی طرف — پناہ لینی ہو — تو — وہ — اللہ کے غضب — میں — لوٹ آیا — اور اس کا ٹھکانا — جہنم ہے — اور وہ — بدترین انجام ہے",
"""۱۔ جنگ میں — بغیر کسی مجبوری کے منہ موڑنا — گناہ کبیرہ۔
۲۔ ’’وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَۃٍ فَقَدْ بَاءَ بِغَضَبٍ مِّنَ اللَّهِ وَمَأْوَاهُ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ‘‘ — اور — جو کوئی — اُس دن — ان سے — منہ موڑے — سوائے اس کے کہ — جنگی چال — کے طور پر ہو — یا — کسی گروہ کی طرف — پناہ لینی ہو — تو — وہ — اللہ کے غضب — میں — لوٹ آیا — اور اس کا ٹھکانا — جہنم ہے — اور وہ — بدترین انجام ہے — یعنی لڑائی کے دوران — بغیر — حیلے اور منصوبہ کے — فرار — اللہ کے غضب اور جہنم کا سبب ہے۔
۳۔ عملی سبق: جنگی فرار — صرف — تاکتیکی چال یا پناہ کے لیے — جائز ہے۔"""
),
1177: (
"پس — تم — نے — انہیں نہیں مارا — لیکن — اللہ نے — انہیں مارا — اور — جب — تم — نے — پھینکا — تو — تم نے — نہیں پھینکا — لیکن — اللہ — نے — پھینکا — اور — تاکہ — اس سے — مؤمنوں کو — ایک اچھا امتحان — آزمائے — بے شک — اللہ — سننے والا جاننے والا ہے",
"""۱۔ بدر میں — ہر کارنامہ — اللہ کی مدد سے۔
۲۔ ’’فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ اللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ اللَّهَ رَمَىٰ وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلَاءً حَسَنًا إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ‘‘ — پس — تم — نے — انہیں نہیں مارا — لیکن — اللہ نے — انہیں مارا — اور — جب — تم — نے — پھینکا — تو — تم نے — نہیں پھینکا — لیکن — اللہ — نے — پھینکا — اور — تاکہ — اس سے — مؤمنوں کو — ایک اچھا امتحان — آزمائے — بے شک — اللہ — سننے والا جاننے والا ہے — یعنی فتح — تمہاری طاقت سے نہیں — اللہ کی مدد سے تھی۔
۳۔ عملی سبق: ہر کامیابی — اللہ کی مدد سے ہے؛ خود پر — فخر نہ کرو۔"""
),
1178: (
"یہ — تمہارے لیے — ہے — اور — یہ کہ اللہ — کافروں کی چال — کو کمزور کر دیتا ہے",
"""۱۔ اللہ — کافروں کی تدبیریں — ناکام بناتا ہے۔
۲۔ ’’ذَٰلِكُمْ وَأَنَّ اللَّهَ مُوهِنُ كَيْدِ الْكَافِرِينَ‘‘ — یہ — تمہارے لیے — ہے — اور — یہ کہ اللہ — کافروں کی چال — کو کمزور کر دیتا ہے — یعنی اللہ — کافروں کے تمام منصوبے — بے اثر کر دیتا ہے۔
۳۔ عملی سبق: اللہ — کافروں کے حیلے — ہمیشہ — کمزور کرتا ہے۔"""
),
}
